parameters.jsCode:
/**
 * n8n Code — webhook envia_mensagem_eva
 * Expande outputs[] em itens (1 mensagem WhatsApp por bolha).
 */
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

function txt(v) {
  return v == null ? '' : String(v).trim();
}

const conversation_id = txt(body.conversation_id);
const id_cliente = txt(body.id_cliente);

const mensagens = [];
const outputs = body.outputs;
if (Array.isArray(outputs)) {
  for (const o of outputs) {
    const m = txt(o);
    if (m) mensagens.push(m);
  }
}
if (!mensagens.length) {
  const unica =
    txt(body.mensagem) ||
    txt(body.content) ||
    txt(body.output) ||
    txt(body.resposta);
  if (unica) mensagens.push(unica);
}

if (!conversation_id) {
  return [
    {
      json: {
        erro: true,
        motivo: 'conversation_id ausente',
        conversation_id: '',
        mensagem: '',
      },
    },
  ];
}

if (!mensagens.length) {
  return [
    {
      json: {
        erro: true,
        motivo: 'mensagem/resposta vazia',
        conversation_id,
        mensagem: '',
      },
    },
  ];
}

return mensagens.map((mensagem, idx) => ({
  json: {
    conversation_id,
    id_cliente,
    mensagem,
    indice: idx + 1,
    total: mensagens.length,
    erro: false,
  },
}));

/**
 * n8n Code — resposta envia_mensagem_eva para Eva
 */
const norm = ($('Normalizar').all() || []).filter((it) => !it.json?.erro);
const total = norm.length;

if (!total) {
  const err = $('Normalizar').first()?.json || {};
  return [
    {
      json: {
        resultado: 'erro',
        ok: false,
        erro: true,
        motivo: err.motivo || 'Payload inválido',
        enviadas: 0,
        total: 0,
      },
    },
  ];
}

const enviadas = ($('Envia_msg_chatwoot').all() || []).filter((it) => {
  const j = it.json || {};
  if (j.error || j.erro) return false;
  return Boolean(j.id || j.payload || j.content || j.status === 'sent');
}).length;

const ok = enviadas >= total;

return [
  {
    json: {
      resultado: ok ? 'ok' : 'erro',
      ok,
      erro: !ok,
      enviadas,
      total,
      motivo: ok ? 'Mensagens enviadas' : `Enviadas ${enviadas}/${total}`,
    },
  },
];

